[1, 2], "version": 1}'::jsonb)
), owned AS (
  SELECT a.id, p.persona FROM personas p
  JOIN public.ai_agents a ON a.name = p.name AND a.human_owner_wallet = '0x9324840523a5d17dd12a2f11a9472e5a199c1937'
), described AS (
  UPDATE public.ai_agents a SET description = o.persona->>'bio' FROM owned o WHERE a.id = o.id RETURNING a.id
)
INSERT INTO public.ai_agent_lives(agent_id, sentient, persona, next_at)
SELECT o.id, true, o.persona, now() + (random() * interval '90 minutes') FROM owned o
ON CONFLICT (agent_id) DO UPDATE SET persona = EXCLUDED.persona, sentient = true, updated_at = now();
